using System.Text;
using ApiClientGenerator.Abstractions.Abstractions;
using ApiClientGenerator.Abstractions.Models;
using ApiClientGenerator.Abstractions.Parsing;

namespace ApiClientGenerator.Flutter;

public sealed class DartRepositoryEmitter(ITypeMapper typeMapper, INamingConvention naming) : IRepositoryEmitter
{
    public string FileExtension => ".dart";
    public string HttpClientFileName => "http.dart";

    public string EmitHttpClient() =>
        """
        // <auto-generated />
        // Этот файл сгенерирован автоматически. Не редактируйте вручную.

        import 'dart:convert';
        import 'package:http/http.dart' as http;

        const baseUrl = '';

        String? _authToken;

        void setAuthToken(String? token) {
          _authToken = token;
        }

        class ApiException implements Exception {
          final int statusCode;
          final String body;

          ApiException(this.statusCode, this.body);

          @override
          String toString() => 'ApiException($statusCode): $body';
        }

        Future<T> httpRequest<T>(
          String method,
          String path, {
          Map<String, dynamic>? query,
          Object? body,
          required T Function(dynamic json) parse,
        }) async {
          final uri = Uri.parse('$baseUrl$path').replace(
            queryParameters: query?.map((k, v) => MapEntry(k, v.toString())),
          );

          final headers = <String, String>{};
          if (_authToken != null) {
            headers['Authorization'] = 'Bearer $_authToken';
          }
          if (body != null) {
            headers['Content-Type'] = 'application/json';
          }

          final request = http.Request(method, uri)..headers.addAll(headers);
          if (body != null) {
            request.body = jsonEncode(body);
          }

          final streamed = await request.send();
          final response = await http.Response.fromStream(streamed);

          if (response.statusCode < 200 || response.statusCode >= 300) {
            throw ApiException(response.statusCode, response.body);
          }

          if (response.statusCode == 204) {
            return parse(null);
          }

          final contentType = response.headers['content-type'] ?? '';
          if (contentType.contains('application/json')) {
            return parse(jsonDecode(response.body));
          }

          return parse(response.body);
        }
        """;

    public string EmitRepository(
        string tag,
        IReadOnlyList<ParsedEndpoint> endpoints,
        IReadOnlySet<string> localModels,
        string relativeImportPrefix)
    {
        var className = $"{naming.ClassName(tag)}Repository";
        var sb = new StringBuilder();

        sb.AppendLine("// <auto-generated />");
        sb.AppendLine();
        sb.AppendLine($"import '{relativeImportPrefix}http.dart';");

        if (localModels.Count > 0)
            sb.AppendLine("import 'models.dart';");

        sb.AppendLine();
        sb.AppendLine($"class {className} {{");

        foreach (var e in endpoints)
        {
            EmitMethod(sb, e, localModels);
            sb.AppendLine();
        }

        sb.AppendLine("}");
        return sb.ToString();
    }

    private void EmitMethod(StringBuilder sb, ParsedEndpoint e, IReadOnlySet<string> localModels)
    {
        var methodName = naming.MethodName(e.OperationId);
        var returnType = ResolveReturnType(e.ResponseBody, localModels);
        var parameters = BuildParameters(e, localModels);
        var pathExpr = BuildPathExpression(e);
        var queryObj = BuildQueryObject(e);
        var parseExpr = BuildParseExpression(e.ResponseBody);

        sb.AppendLine($"  static Future<{returnType}> {methodName}({parameters}) async {{");
        sb.AppendLine($"    return httpRequest<{returnType}>(");
        sb.AppendLine($"      '{e.Method}',");
        sb.AppendLine($"      {pathExpr},");

        if (queryObj is not null)
            sb.AppendLine($"      query: {queryObj},");

        if (e.RequestBody is not null)
            sb.AppendLine("      body: body,");

        sb.AppendLine($"      parse: {parseExpr},");
        sb.AppendLine("    );");
        sb.AppendLine("  }");
    }

    private string BuildParameters(ParsedEndpoint e, IReadOnlySet<string> localModels)
    {
        var parts = new List<string>();

        foreach (var p in e.Parameters.Where(x => x.In == "path"))
        {
            var type = ResolveSchemaType(p.Schema, localModels);
            parts.Add($"{naming.PropertyName(p.Name)} {type}");
        }

        foreach (var p in e.Parameters.Where(x => x.In == "query"))
        {
            var type = ResolveSchemaType(p.Schema, localModels);
            var modifier = p.Required ? "required " : "";
            var fieldType = p.Required ? type : typeMapper.MakeNullable(type);
            parts.Add($"{modifier}{naming.PropertyName(p.Name)} {fieldType}");
        }

        if (e.RequestBody is not null)
            parts.Add($"required {ResolveSchemaType(e.RequestBody, localModels)} body");

        return string.Join(", ", parts);
    }

    private string BuildPathExpression(ParsedEndpoint e)
    {
        var path = e.Path;

        foreach (var p in e.Parameters.Where(x => x.In == "path"))
        {
            var name = naming.PropertyName(p.Name);
            path = path.Replace($"{{{p.Name}}}", $"${name}");
        }

        return $"'{path}'";
    }

    private string? BuildQueryObject(ParsedEndpoint e)
    {
        var queryParams = e.Parameters.Where(p => p.In == "query").ToList();
        if (queryParams.Count == 0) return null;

        var entries = queryParams.Select(p =>
        {
            var name = naming.PropertyName(p.Name);
            return $"'{p.Name}': {name}";
        });

        return $"{{ {string.Join(", ", entries)} }}";
    }

    private string BuildParseExpression(OpenApiSchema? schema)
    {
        if (schema is null)
            return "(_) => null";

        if (schema.Ref is not null)
        {
            var name = schema.Ref.Split('/')[^1];
            return $"(json) => {name}.fromJson(json as Map<String, dynamic>)";
        }

        if (schema is { Type: "array", Items: not null })
        {
            if (schema.Items.Ref is not null)
            {
                var name = schema.Items.Ref.Split('/')[^1];
                return
                    $"(json) => (json as List<dynamic>).map((e) => {name}.fromJson(e as Map<String, dynamic>)).toList()";
            }

            return "(json) => json as List<dynamic>";
        }

        return schema.Type switch
        {
            "string" => schema.Format switch
            {
                "date-time" => "(json) => DateTime.parse(json as String)",
                "date" => "(json) => DateTime.parse(json as String)",
                _ => "(json) => json as String"
            },
            "integer" => "(json) => json as int",
            "number" => "(json) => (json as num).toDouble()",
            "boolean" => "(json) => json as bool",
            "object" => "(json) => json as Map<String, dynamic>",
            _ => "(json) => json"
        };
    }

    private string ResolveReturnType(OpenApiSchema? schema, IReadOnlySet<string> localModels) =>
        schema is null ? "void" : ResolveSchemaType(schema, localModels);

    private string ResolveSchemaType(OpenApiSchema schema, IReadOnlySet<string> localModels)
    {
        if (schema.Ref is not null)
        {
            var name = schema.Ref.Split('/')[^1];
            return typeMapper.MapReference(name, localModels.Contains(name));
        }

        if (schema.Enum is { Count: > 0 })
            return "String";

        var baseType = schema.Type switch
        {
            "string" => typeMapper.MapPrimitive("string", schema.Format),
            "integer" => typeMapper.MapPrimitive("integer", schema.Format),
            "number" => typeMapper.MapPrimitive("number", schema.Format),
            "boolean" => typeMapper.MapPrimitive("boolean", schema.Format),
            "array" => schema.Items is not null
                ? typeMapper.MapArray(ResolveSchemaType(schema.Items, localModels))
                : typeMapper.MapArray(typeMapper.MapUnknown()),
            "object" => typeMapper.MapObject(),
            _ => typeMapper.MapUnknown()
        };

        return schema.Nullable ? typeMapper.MakeNullable(baseType) : baseType;
    }
}